<?php
declare(strict_types=1);require_once __DIR__.'/config/erp.php';$pdo=srnu_db();$id=(int)($_GET['id']??0);$cur=srnu_obtener_cotizacion($id);if(!$cur){http_response_code(404);exit('Cotización no encontrada');}$s=$pdo->prepare('SELECT * FROM cotizacion_versiones WHERE cotizacion_id=? ORDER BY version_no DESC');$s->execute([$id]);$versions=$s->fetchAll();
function snap(array $versions,int $v,array $cur):array{if($v===0)return $cur;foreach($versions as $r)if((int)$r['version_no']===$v)return json_decode($r['snapshot_json'],true)?:[];return $cur;}function itemmap(array $s):array{$m=[];foreach(($s['items']??[]) as $i)$m[trim((string)$i['concepto'])]=$i;return $m;}
$a=(int)($_GET['a']??($versions[0]['version_no']??0));$b=(int)($_GET['b']??0);$sa=snap($versions,$a,$cur);$sb=snap($versions,$b,$cur);$ma=itemmap($sa);$mb=itemmap($sb);$keys=array_unique(array_merge(array_keys($ma),array_keys($mb)));sort($keys);
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Comparar versiones · SRNU</title><?=srnu_ui_head()?></head><body><?php srnu_appbar('cotizaciones');?><main class="w"><div class="srnu-page-heading"><div><h1>Comparar versiones</h1><p><?=eh($cur['folio'])?> · cambios en conceptos e importes.</p></div><a class="btn light" href="versiones.php?id=<?=$id?>">← Versiones</a></div><form class="panel erp-form cols-3" style="padding:18px"><input type="hidden" name="id" value="<?=$id?>"><select name="a"><option value="0" <?=$a===0?'selected':''?>>Actual</option><?php foreach($versions as $v):?><option value="<?=$v['version_no']?>" <?=$a===$v['version_no']?'selected':''?>>Versión <?=$v['version_no']?> · <?=eh($v['created_at'])?></option><?php endforeach;?></select><select name="b"><option value="0" <?=$b===0?'selected':''?>>Actual</option><?php foreach($versions as $v):?><option value="<?=$v['version_no']?>" <?=$b===$v['version_no']?'selected':''?>>Versión <?=$v['version_no']?> · <?=eh($v['created_at'])?></option><?php endforeach;?></select><button class="btn blue">Comparar</button></form><div class="kpi-grid" style="margin-top:16px"><div class="kpi"><small>Total A</small><strong><?=emoney($sa['total']??0)?></strong></div><div class="kpi"><small>Total B</small><strong><?=emoney($sb['total']??0)?></strong></div><div class="kpi"><small>Diferencia</small><strong><?=emoney((float)($sb['total']??0)-(float)($sa['total']??0))?></strong></div><div class="kpi"><small>Conceptos comparados</small><strong><?=count($keys)?></strong></div></div><section class="tablebox" style="margin-top:16px"><table><thead><tr><th>Concepto</th><th>A</th><th>B</th><th>Cambio</th></tr></thead><tbody><?php foreach($keys as $k):$ia=$ma[$k]??null;$ib=$mb[$k]??null;$ta=$ia?(float)$ia['total']:0;$tb=$ib?(float)$ib['total']:0;$status=!$ia?'Agregado':(!$ib?'Eliminado':(abs($ta-$tb)>.009?'Modificado':'Sin cambio'));?><tr><td><?=eh($k)?></td><td><?=$ia?emoney($ta).' · Cant. '.eh($ia['cantidad']):'—'?></td><td><?=$ib?emoney($tb).' · Cant. '.eh($ib['cantidad']):'—'?></td><td><span class="badge <?=$status==='Agregado'?'badge-green':($status==='Eliminado'?'badge-red':($status==='Modificado'?'badge-orange':'badge-blue'))?>"><?=eh($status)?></span><?php if($ia&&$ib&&abs($ta-$tb)>.009):?> <?=emoney($tb-$ta)?><?php endif;?></td></tr><?php endforeach;?></tbody></table></section></main></body></html>
